package bidi

import (
	"bufio"
	"compress/gzip"
	"fmt"
	"os"
	"strings"
	"testing"
)

// orderGoldenFile holds BidiText.Transform(BidiTransform) vectors recorded from the
// JTOpen implementation, generated by gen/OrderGolden.java (mode "order").
// Line format, tab separated:
//
//	id, inFlags, outFlags, bits, delimiters, arabic, inHex, result
//
// result is "EXC:<name>" or outHex|s2dHex|d2sHex|pmHex|inpCount|outCount.
const orderGoldenFile = "testdata/order_golden.txt.gz"

// openGolden opens a gzipped golden file and returns a scanner over its lines.
func openGolden(t *testing.T, name string) (*bufio.Scanner, func()) {
	t.Helper()
	f, err := os.Open(name)
	if err != nil {
		t.Fatalf("open golden file: %v", err)
	}
	zr, err := gzip.NewReader(f)
	if err != nil {
		f.Close()
		t.Fatalf("gzip: %v", err)
	}
	sc := bufio.NewScanner(zr)
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	return sc, func() {
		zr.Close()
		f.Close()
	}
}

// runTransform calls BidiText.Transform and reports a panic (the Java RuntimeException).
func runTransform(src *BidiText, bdx *BidiTransform) (dst *BidiText, panicked bool) {
	defer func() {
		if recover() != nil {
			panicked = true
		}
	}()
	return src.Transform(bdx), false
}

// decodeInts decodes n big-endian 8-hex-digit int32 values (Java %08X of an int).
func decodeInts(t *testing.T, hexs string, n int) []int32 {
	t.Helper()
	if len(hexs) != 8*n {
		t.Fatalf("int map: want %d hex digits, got %d", 8*n, len(hexs))
	}
	out := make([]int32, n)
	for i := range out {
		var v uint32
		if _, err := fmt.Sscanf(hexs[i*8:i*8+8], "%08X", &v); err != nil {
			t.Fatalf("bad int hex %q: %v", hexs[i*8:i*8+8], err)
		}
		out[i] = int32(v)
	}
	return out
}

func decodeBytes(t *testing.T, hexs string, n int) []byte {
	t.Helper()
	if len(hexs) != 2*n {
		t.Fatalf("byte map: want %d hex digits, got %d", 2*n, len(hexs))
	}
	out := make([]byte, n)
	for i := range out {
		var v byte
		if _, err := fmt.Sscanf(hexs[i*2:i*2+2], "%02X", &v); err != nil {
			t.Fatalf("bad byte hex %q: %v", hexs[i*2:i*2+2], err)
		}
		out[i] = v
	}
	return out
}

func TestOrderGolden(t *testing.T) {
	sc, closeFn := openGolden(t, orderGoldenFile)
	defer closeFn()

	total, changed, panics, mapsChecked := 0, 0, 0, 0
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Split(line, "\t")
		if len(fields) != 8 {
			t.Fatalf("vector %d: want 8 fields, got %d", total, len(fields))
		}
		id, inA, outA, bits, delimHex, arab, inHex, result := fields[0], fields[1], fields[2], fields[3],
			fields[4], fields[5], fields[6], fields[7]
		if len(bits) != 9 {
			t.Fatalf("vector %s: bad bits %q", id, bits)
		}

		bdx := NewBidiTransform()
		bdx.Flags.SetAllFlags(NewBidiFlagSetFromChars(charsOf(outA)))
		bdx.ImpToImp = bits[0] == '1'
		bdx.RoundTrip = bits[1] == '1'
		bdx.WinCompatible = bits[2] == '1'
		bdx.InsertMarkers = bits[3] == '1'
		bdx.RemoveMarkers = bits[4] == '1'
		bdx.WordBreak = bits[5] == '1'
		bdx.SrcToDstMapRequired = bits[6] == '1'
		bdx.DstToSrcMapRequired = bits[7] == '1'
		bdx.PropertyMapRequired = bits[8] == '1'
		if delimHex != "-" {
			bdx.Delimiters = decodeUnits(t, delimHex)
		}
		if arab != "-" {
			bdx.Options = NewArabicOptionSetFromChars(charsOf(arab))
		}
		src := NewBidiTextFromData(NewBidiFlagSetFromChars(charsOf(inA)), decodeUnits(t, inHex))

		dst, panicked := runTransform(src, bdx)
		if strings.HasPrefix(result, "EXC:") {
			if !panicked {
				t.Errorf("vector %s: expected panic (%s)", id, result)
			}
			panics++
			total++
			continue
		}
		if panicked {
			t.Errorf("vector %s: unexpected panic, want %s", id, result)
			total++
			continue
		}

		parts := strings.Split(result, "|")
		if len(parts) != 6 {
			t.Fatalf("vector %s: want 6 result parts, got %d", id, len(parts))
		}
		if got := encodeUnits(dst.Data[dst.Offset : dst.Offset+dst.Count]); got != parts[0] {
			t.Errorf("vector %s (in %s out %s bits %s delim %s arab %s)\n input %s\n  got %s\n want %s",
				id, inA, outA, bits, delimHex, arab, inHex, got, parts[0])
		}
		if bdx.InpCount != atoiChecked(t, parts[4]) || bdx.OutCount != atoiChecked(t, parts[5]) {
			t.Errorf("vector %s: counts got %d/%d want %s/%s", id, bdx.InpCount, bdx.OutCount, parts[4], parts[5])
		}
		if bdx.SrcToDstMapRequired {
			want := decodeInts(t, parts[1], bdx.InpCount)
			for i, w := range want {
				if int32(bdx.SrcToDstMap[i]) != w {
					t.Errorf("vector %s: srcToDst[%d] got %d want %d", id, i, bdx.SrcToDstMap[i], w)
					break
				}
			}
			mapsChecked++
		}
		if bdx.DstToSrcMapRequired {
			want := decodeInts(t, parts[2], bdx.OutCount)
			for i, w := range want {
				if int32(bdx.DstToSrcMap[i]) != w {
					t.Errorf("vector %s: dstToSrc[%d] got %d want %d", id, i, bdx.DstToSrcMap[i], w)
					break
				}
			}
			mapsChecked++
		}
		if bdx.PropertyMapRequired {
			want := decodeBytes(t, parts[3], bdx.InpCount)
			for i, w := range want {
				if bdx.PropertyMap[i] != w {
					t.Errorf("vector %s: propertyMap[%d] got %02X want %02X", id, i, bdx.PropertyMap[i], w)
					break
				}
			}
			mapsChecked++
		}
		if parts[0] != inHex {
			changed++
		}
		total++
	}
	if err := sc.Err(); err != nil {
		t.Fatalf("reading golden file: %v", err)
	}
	if total < 10000 {
		t.Fatalf("only %d golden vectors, expected at least 10000", total)
	}
	if changed < total/3 {
		t.Errorf("only %d of %d vectors changed the text; the vectors look degenerate", changed, total)
	}
	t.Logf("order golden vectors: %d (changed text: %d, exception cases: %d, maps checked: %d)",
		total, changed, panics, mapsChecked)
}

// atoiChecked parses a decimal count from the golden file.
func atoiChecked(t *testing.T, s string) int {
	t.Helper()
	var v int
	if _, err := fmt.Sscanf(s, "%d", &v); err != nil {
		t.Fatalf("bad count %q: %v", s, err)
	}
	return v
}
